import osimport string
def clog2(value):    base2exp = 0    num = value - 1    if(num <= 0):        PluginUtil.post_error("ERROR  --  Invalid input")        return 0    else:        while(num > 0):            num = num // 2            base2exp = base2exp + 1    return base2exp
