def check_byte_enable_parameter(data_width_a, byte_en, family):	if(byte_en):		if(data_width_a < 16):			PluginUtil.post_error("ERROR -- Total Byte Width < 1, please use WDATA_WIDTH = 16 or greater")			return 0		elif(family == "iCE40UP"):			if(not (data_width_a % 8 == 0)):				PluginUtil.post_error("ERROR -- DATA_WIDTH is not divisible by 8, cannot use byte_enable")				return 0		elif(family == "LIFCL" or family == "LATG1" or family == "LAV-AT" or family == "ap6a00" or family == "ap6a00b" or family == "ap6a400"):			if(not ((data_width_a % 8 == 0) or (data_width_a % 9 == 0))):				PluginUtil.post_error("ERROR -- DATA_WIDTH is not divisible by 8 or 9, cannot use byte_enable")				return 0	return 1
def check_if_byte_en_required(data_width_a,data_width_b,byte_size):    if(((data_width_a + data_width_b) > (2 * byte_size)) and       ((data_width_a > byte_size) and (data_width_b > byte_size))):        return 1    else:        return 0
