def get_max_bits(family):	if(family == "iCE40UP"):		return (4096 * 30)	elif(family == "LIFCL"):		return (18 * 1024 * 84)	elif(family == "LATG1" or family == "LAV-AT" or family == "ap6a00" or family == "ap6a00b" or family == "ap6a400"):		return (18 * 2048 * 2970)	return (2 ** 30)	def cal_addr_depth_range(addr_depth_a,data_width_a,data_width_b):    min_addr_depth = 2    max_addr_depth = 65536
    if(data_width_a == data_width_b):        addr_depth_b = addr_depth_a    else:        addr_depth_b = (addr_depth_a * data_width_a) // data_width_b
    if((addr_depth_b > max_addr_depth) or (addr_depth_b < min_addr_depth)):        return (min_addr_depth,max_addr_depth)    else:        return (addr_depth_b,addr_depth_b)
def cal_data_width_range(addr_depth_a,data_width_a,addr_depth_b):    min_data_width = 1    max_data_width = 512    if(addr_depth_a == addr_depth_b):        data_width_b = data_width_a    else:        data_width_b = (addr_depth_a * data_width_a) // addr_depth_b
    if((data_width_b > max_data_width) or (data_width_b < min_data_width)):        return (min_data_width,max_data_width)    else:        return (data_width_b,data_width_b)
