def get_init_file(init_file,init_mode,addr_depth,data_width):	return init_file#################################################
def create4DArray(a,b,c,d):    p = [0]*a    for i in range(a):        p[i] = [0]*b        for j in range(b):            p[i][j] = [0]*c            for k in range(c):                p[i][j][k] = [0]*d    return p
def create2DArray(a,b):    p = [0]*a    for i in range(a):        p[i] = [0]*b    return p
def roundUP(q,r):	if(r == 1):		return q	elif(q <= r):		return 1	else:		m = int(q/r)		if(q%r == 0):			return m		return m+1
def checkIfHex(character):    return (character == "0" or character == "1" or character == "2" or character == "3" or            character == "4" or character == "5" or character == "6" or character == "7" or            character == "8" or character == "9" or character == "A" or character == "B" or            character == "C" or character == "D" or character == "E" or character == "F")
def checkIfBin(character):	return (character == "0" or character == "1")
def hex_to_bin(hex_data, pos):	if(pos == 0):		if(hex_data == "1" or hex_data == "3" or hex_data == "5" or hex_data == "7" or hex_data == "9" or hex_data == "B" or hex_data == "D" or hex_data == "F"):			return int(1)	elif(pos == 1):		if(hex_data == "2" or hex_data == "3" or hex_data == "6" or hex_data == "7" or hex_data == "A" or hex_data == "B" or hex_data == "E" or hex_data == "F"):			return int(1)	elif(pos == 2):		if (hex_data == "4" or hex_data == "5" or hex_data == "6" or hex_data == "7" or hex_data == "C" or hex_data == "D" or hex_data == "E" or hex_data == "F"):			return int(1)	elif(pos == 3):		if (hex_data == "8" or hex_data == "9" or hex_data == "A" or hex_data == "B" or hex_data == "C" or hex_data == "D" or hex_data == "E" or hex_data == "F"):			return int(1)	return int(0)
def getBin(x_char):    if(x_char == "1"):        return 1    return 0
def bin_to_hex(bin3, bin2, bin1, bin0):    b3 = str(bin3)    b2 = str(bin2)    b1 = str(bin1)    b0 = str(bin0)    bin_eq = b3 + b2 + b1 + b0    return {        "0000": "0",        "0001": "1",        "0010": "2",        "0011": "3",        "0100": "4",        "0101": "5",        "0110": "6",        "0111": "7",        "1000": "8",        "1001": "9",        "1010": "A",        "1011": "B",        "1100": "C",        "1101": "D",        "1110": "E",        "1111": "F"    }.get(bin_eq, "0")
def EBRimpl(data_impl, depth_impl, dwid, adepth):    return roundUP(dwid, data_impl) * roundUP(adepth, depth_impl)
def getMinDataWidth(addr_depth, data_width, byte_en, ecc_en, family):	if(family == "iCE40UP"):		r = 2		m = EBRimpl(2, 2048, data_width, addr_depth)		n = EBRimpl(4, 1024, data_width, addr_depth)		if(n < m):			r = 4			m = n		n = EBRimpl(8, 512, data_width, addr_depth)		if(n < m):			r = 8			m = n		n = EBRimpl(16, 256, data_width, addr_depth)		if(n < m):			return 16		else:			return r	elif(family == "LIFCL"):		if(ecc_en):			r = 32			return r		elif(byte_en and data_width%9 != 0):			r = 1			m = EBRimpl(1, 16384, data_width, addr_depth)			n = EBRimpl(2, 8192, data_width, addr_depth)			if(n < m):				r = 2				m = n			n = EBRimpl(4, 4096, data_width, addr_depth)			if(n < m):				r = 4				m = n			n = EBRimpl(8, 2048, data_width, addr_depth)			if(n < m):				r = 8				m = n			n = EBRimpl(16, 1024, data_width, addr_depth)			if(n < m):				r = 16				m = n			n = EBRimpl(32, 512, data_width, addr_depth)			if(n < m):				r = 32			return r		else:			r = 1			m = EBRimpl(1, 16384, data_width, addr_depth)			n = EBRimpl(2, 8192, data_width, addr_depth)			if(n < m):				r = 2				m = n			n = EBRimpl(4, 4096, data_width, addr_depth)			if(n < m):				r = 4				m = n			n = EBRimpl(9, 2048, data_width, addr_depth)			if(n < m):				r = 9				m = n			n = EBRimpl(18, 1024, data_width, addr_depth)			if(n < m):				r = 18				m = n			n = EBRimpl(36, 512, data_width, addr_depth)			if(n < m):				r = 36			return r	elif(family == "LATG1" or family == "LAV-AT" or family == "ap6a00" or family == "ap6a00b" or family == "ap6a400"):		if(ecc_en):			r = 64			return r		elif((byte_en and data_width%9 != 0)):			r = 64			m = EBRimpl(64, 512, data_width, addr_depth)			n = EBRimpl(32, 1024, data_width, addr_depth)			if(n <= m):				r = 32				m = n			n = EBRimpl(16, 2048, data_width, addr_depth)			if(n <= m):				r = 16				m = n			n = EBRimpl(8, 4096, data_width, addr_depth)			if(n <= m):				r = 8				m = n			n = EBRimpl(4, 8192, data_width, addr_depth)			if(n <= m):				m = n				r = 4			n = EBRimpl(2, 16384, data_width, addr_depth)			if(n <= m):				r = 2				m = n			n = EBRimpl(1, 32768, data_width, addr_depth)			if(n <= m):				r = 1			return r		else:			r = 72			m = EBRimpl(72, 512, data_width, addr_depth)			n = EBRimpl(36, 1024, data_width, addr_depth)			if(n <= m):				r = 36				m = n			n = EBRimpl(18, 2048, data_width, addr_depth)			if(n <= m):				r = 18				m = n			n = EBRimpl(9, 4096, data_width, addr_depth)			if(n <= m):				r = 9				m = n			n = EBRimpl(4, 8192, data_width, addr_depth)			if(n <= m):				r = 4				m = n			n = EBRimpl(2, 16384, data_width, addr_depth)			if(n <= m):				r = 2				m = n			n = EBRimpl(1, 32768, data_width, addr_depth)			if(n <= m):				r = 1			return r	return data_width
def convdwid_to_depth(dwid, family):	if(family == "iCE40UP"):		return {			16: 256,			8: 512,			4: 1024,			2: 2048		}.get(dwid, 1024)	elif(family == "LIFCL"):		return {			36: 512,			32: 512,			18: 1024,			16: 1024,			9: 2048,			8: 2048,			4: 4096,			2: 8192,			1: 16384		}.get(dwid, 1024)	elif(family == "LATG1" or family == "LAV-AT" or family == "ap6a00" or family == "ap6a00b" or family == "ap6a400"):		return {			72: 512,			64: 512,			36: 1024,			32: 1024,			18: 2048,			16: 2048,			9: 4096,			8: 4096,			4: 8192,			2: 16384,			1: 32768		}.get(dwid, 1024)
def getSize(addr_depth, data_width, byte_en, ecc_en, family):	x = getMinDataWidth(addr_depth, data_width, byte_en, ecc_en, family)	y = convdwid_to_depth(x, family)	return [roundUP(data_width, x), roundUP(addr_depth, y), x, y]
def neg_r(bit):	if(bit == 0):		return 1	return 0
